using PetStock.API.Analytics.Domain.Model.Commands;

namespace PetStock.API.Analytics.Domain.Model.Aggregates;

/// <summary>Operational report generated by a user.</summary>
public partial class Report
{
    // Constructor for EF Core
    protected Report()
    {
        ReportType = string.Empty;
        FileFormat = string.Empty;
    }

    /// <summary>Creates a report from the command.</summary>
    public Report(CreateReportCommand command)
    {
        ArgumentNullException.ThrowIfNull(command);
        UserId = command.UserId;
        ReportType = command.ReportType;
        FileFormat = command.FileFormat;
        GeneratedAt = DateTimeOffset.UtcNow;
    }

    public int Id { get; private set; }
    public int UserId { get; private set; }
    public string ReportType { get; private set; }

    /// <summary>For now only PDF.</summary>
    public string FileFormat { get; private set; }

    public DateTimeOffset GeneratedAt { get; private set; }
}
